"""Write regional review hubs and an auditable town-coverage table."""
from pathlib import Path
import json,csv,html
P=Path(__file__).resolve().parent;A=P.parent;c=json.load(open(A/'regions/catalog.json'));registry=json.load(open(A/'regions/package-registry.json'));landings={t['town_id']:t for t in json.load(open(A/'landing/index.json'))['towns']};allrows=[]
for rid in ['nature-coast','emerald-coast']:
 r=next(r for r in c['regions'] if r['id']==rid);root=A/'regions/packages'/rid;root.mkdir(exist_ok=True);cards=[];accuracy=[];prices=[];reports=[]
 for tid in r['towns']:
  t=next(t for t in c['towns'] if t['id']==tid);name=html.escape(t['name']);review='../../30a-review/index.html' if tid=='30a' else '../'+registry[tid].strip('/').split('/')[-1]+'/atlas-review.html';pkg=A/'regions'/registry[tid] if tid in registry else None
  if pkg:
   accuracy+=list(csv.DictReader(open(pkg/'accuracy.csv')));prices+=list(csv.DictReader(open(pkg/'district-price-sources.csv')));reports.append(json.load(open(pkg/'report.json')))
  cards.append(f'<article><h2>{name}</h2><p>{html.escape(t["blurb"])}</p><p><a href="{review}">Town review and OSM overlay</a> · <a href="../../../explore_coast.html?view={tid}&level=town">Explore town</a> · <a href="../../../landing/{"nature" if rid=="nature-coast" else "emerald"}-review.html#{tid}">Both landing zooms</a></p><a href="../../../explore_coast.html?view={tid}&level=town"><img loading="lazy" src="../../../landing/{tid}.webp" alt="{name} waterfront hero"></a></article>');allrows.append({'region':rid,'town_id':tid,'name':t['name'],'package':registry.get(tid,'approved 30A reference'),'landing_zoom_levels':2,'images':4,'status':'built; physical-phone speed unverified'})
 for name,rows in [('accuracy.csv',accuracy),('district-price-sources.csv',prices)]:
  with (root/name).open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=rows[0].keys());w.writeheader();w.writerows(rows)
 (root/'report.json').write_text(json.dumps({'region':rid,'towns':r['towns'],'packages':reports,'pipeline_changed':False,'phone_hardware_verified':False,'notes':['Source-alignment checks are not an independent ground survey.','Prices retain metric and period; some small communities have thin or older published medians.','Facade palettes, canopy crowns and boat occupancy are illustrated; source geometries retained.']},indent=2)+'\n')
 (root/'atlas-review.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(r['map'])+' · Florida Coastal</title><style>body{font:16px system-ui;background:#f4eedf;color:#345047;margin:24px}main{max-width:1300px;margin:auto}article{background:#fffaf0;margin:30px 0;padding:24px}img{width:100%;aspect-ratio:8/5;object-fit:contain}a{color:#a34c27}p{line-height:1.5}</style><main><h1>'+html.escape(r['map'])+'</h1><p>'+str(len(r['towns']))+' towns and coastal communities · shared locked pipeline.</p><p><a href="../../../explore_coast.html?view='+r['towns'][0]+'&level=region">Open regional atlas</a> · <a href="accuracy.csv">Accuracy CSV</a> · <a href="district-price-sources.csv">Sourced medians</a> · <a href="report.json">Reports</a></p>'+''.join(cards)+'<p>© OpenStreetMap contributors, ODbL · ESA WorldCover 2021, CC BY 4.0 · Supplemental Microsoft footprints, CDLA Permissive 2.0. Source alignment is not a ground survey. Physical-phone speed unverified.</p></main></html>')
with (A/'regions/coast-coverage.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=allrows[0].keys());w.writeheader();w.writerows(allrows)
print('Covered',len(allrows),'towns/communities across the two coasts')
